import{_ as r,C as n,c as a,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Orders","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/orders-payments/orders.md","filePath":"master/sales/point-of-sale/orders-payments/orders.md","lastUpdated":1792041590000}'),l={name:"master/sales/point-of-sale/orders-payments/orders.md"};function d(g,e,h,u,c,p){const s=n("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="orders" tabindex="-1">Orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;Orders&quot;">​</a></h1><p>An order is the record of one sale made at the till. It holds the products, the customer, the payments and the state. You use the Orders page to search past sales, open an order, create its invoice or return products.</p><blockquote><p><strong>In simple words:</strong> One sale at the till is one order. This page is the list of all of them.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Go to <code>Point of Sale → Orders → Orders</code>.</p>',5)),o(s,{src:"/images1/pos/orders_list.png",alt:"Point of Sale → Orders → Orders list showing TNE/00001, TNE/00002 and the refund TNE/00002 REFUND"}),e[1]||(e[1]=t('<p>The page has these tabs:</p><ul><li><strong>Default:</strong> All orders.</li><li><strong>Settled:</strong> Orders that are <strong>Paid</strong>, <strong>Posted</strong> or <strong>Invoiced</strong>.</li><li><strong>Ongoing:</strong> Orders still in the <strong>New</strong> state, not yet paid.</li><li><strong>Refunds:</strong> Orders that return products from an earlier order.</li></ul><p>You can also pick <strong>Failed Operations</strong> from the saved views menu. It lists orders whose stock move needs attention.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Order Ref:</em></strong> The order number, such as <strong>TNE/00001</strong>. A refund order ends with <strong>REFUND</strong>.</li><li><strong><em>Session:</em></strong> The session the order belongs to, such as <strong>TNE/SESSION/00002</strong>.</li><li><strong><em>Date:</em></strong> When the order was made.</li><li><strong><em>Point of Sale:</em></strong> The register, such as <strong>TechNest Electronics</strong>.</li><li><strong><em>Receipt Number:</em></strong> The number printed on the receipt, such as <strong>00004-009-0001</strong>.</li><li><strong><em>Customer:</em></strong> The customer on the order.</li><li><strong><em>Cashier:</em></strong> The user who sold it.</li><li><strong><em>Total:</em></strong> The order total. Refunds show a negative amount. The footer adds up the column.</li><li><strong><em>Status:</em></strong> The order state as a badge.</li></ul><p>Hidden columns you can switch on: <strong>Tracking Number</strong>, <strong>Edited</strong>, <strong>Paid</strong>, <strong>Failed Operation</strong> and <strong>Invoiced</strong>.</p><h3 id="group-and-filter" tabindex="-1">Group and filter <a class="header-anchor" href="#group-and-filter" aria-label="Permalink to &quot;Group and filter&quot;">​</a></h3><ul><li>Click <strong>Group by</strong> to group by <strong>Session</strong>, <strong>Point of Sale</strong>, <strong>Status</strong> or <strong>Ordered At</strong>.</li><li>Use the filters for <strong>Status</strong>, <strong>Session</strong> and <strong>Point of Sale</strong>.</li></ul><h2 id="order-states" tabindex="-1">Order states <a class="header-anchor" href="#order-states" aria-label="Permalink to &quot;Order states&quot;">​</a></h2><ul><li><strong>New:</strong> The cashier has started the order. Nothing is paid yet.</li><li><strong>Paid:</strong> The customer paid in full.</li><li><strong>Posted:</strong> The session was closed and the order was posted to accounting.</li><li><strong>Invoiced:</strong> A customer invoice exists for the order.</li><li><strong>Cancelled:</strong> The order was cancelled.</li></ul><h2 id="open-an-order" tabindex="-1">Open an order <a class="header-anchor" href="#open-an-order" aria-label="Permalink to &quot;Open an order&quot;">​</a></h2><p>Click a row to open it. The top of the page shows the state as steps. The <strong>General</strong> section shows the order, customer, session, order date and register.</p>',12)),o(s,{src:"/images1/pos/order_view_top.png",alt:"Order TNE/00001 view page with state steps, General section and Order Line tab"}),e[2]||(e[2]=t('<p>The tabs below hold the details.</p><ul><li><strong>Order Line:</strong> Product, <strong>Quantity</strong>, <strong>Unit Price</strong>, <strong>Taxes</strong>, <strong>Discount (%)</strong> and <strong>Amount</strong>. The totals show <strong>Untaxed Amount</strong>, <strong>Taxes</strong>, <strong>Amount Total</strong> and <strong>Margin</strong>.</li><li><strong>Payments:</strong> Each payment with its method, amount and time. Change given back shows as a negative line.</li><li><strong>Extra Info:</strong> <strong>Receipt Number</strong>, <strong>Tracking Number</strong>, <strong>Email</strong> and <strong>Mobile</strong>.</li><li><strong>Other Information:</strong> <strong>Reference</strong>, stock <strong>Operation</strong>, <strong>Cashier</strong>, <strong>Paid</strong> and <strong>Change</strong>.</li></ul><p>Use the links above the page to move between <strong>View</strong>, <strong>Edit</strong>, <strong>Invoices</strong> and <strong>Deliveries</strong>. The last two show the invoice and the stock transfer made for the order.</p><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><p>Order <strong>TNE/00001</strong> was sold to Sofia Rossi. It has 2 Glide Wireless Mouse at 1,299 and 1 BudsAir Wireless Earbuds at 3,999. The total is 6,597. She paid 7,000 in cash, so <strong>Change</strong> is 403.</p>',5)),o(s,{src:"/images1/pos/order_view_payments.png",alt:"Order TNE/00001 Payments tab with Cash 7,000 and change of 403"}),e[3]||(e[3]=t('<h2 id="edit-an-order" tabindex="-1">Edit an order <a class="header-anchor" href="#edit-an-order" aria-label="Permalink to &quot;Edit an order&quot;">​</a></h2><ol><li>Open the order and click <strong>Edit</strong>.</li><li>Change the <strong>Customer</strong> if needed. You cannot change it once the order is <strong>Invoiced</strong>.</li><li>Review the <strong>Products</strong>, <strong>Payments</strong> and <strong>Extra Info</strong> tabs. Product lines are read only.</li><li>Click <strong>Save changes</strong>.</li></ol>',2)),o(s,{src:"/images1/pos/order_edit.png",alt:"Edit page of order TNE/00001 with the Products tab showing both lines"}),e[4]||(e[4]=t('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>The buttons at the top of the order page depend on its state.</p><ul><li><strong>Invoice:</strong> Creates the customer invoice for a settled order. Confirm the window. A message says the invoice was posted and paid, and the state becomes <strong>Invoiced</strong>. See <a href="./../selling/invoice-a-pos-order.html">Invoice a POS order</a>.</li><li><strong>Return Products:</strong> Opens a window to refund. Pick the <strong>Refund Payment Method</strong>, tick the lines, set the <strong>Quantity</strong> and confirm. Aureus creates a refund order such as <strong>TNE/00002 REFUND</strong>. The button reads <strong>Refunded</strong> when nothing is left to return. See <a href="./../selling/refunds.html">Refunds</a>.</li><li><strong>Retry Operation:</strong> Appears when the stock move failed. Use it to try the stock move again.</li><li><strong>Chatter:</strong> Opens messages and notes on the order.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Return Products only shows on settled orders. It does not show on a refund order.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>After a session is closed, the <strong>Invoice</strong> button no longer shows for orders of that session. Invoice the order before you close the session.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./payments.html">Payments</a></li><li><a href="./customers.html">Customers</a></li><li><a href="./../sessions/close-session.html">Close a session</a></li><li><a href="./../reporting/orders-report.html">Orders report</a></li></ul>',7))])}const T=r(l,[["render",d]]);export{f as __pageData,T as default};
